from collections import deque,defaultdict
R,C=len(grid),len(grid[0])
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v not in (0,2) and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]]==v and z not in seen:
      seen.add(z);q.append(z)
   comps.append((v, min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells),sorted(cells)))
[(v,(r0,r1,c0,c1),len(cs),cs) for v,r0,r1,c0,c1,cs in comps]

# Define 4-connected color components from test and assign adjacent markers by inspection.
# Translate each component, including its 2-marker cells, into the assembled chain anchored on 4.
parts = {
 '1': {'color':1, 'dr':-3,'dc':7, 'markers':[(5,8),(5,13)]},
 '3': {'color':3, 'dr':-9,'dc':13, 'markers':[(11,2),(11,7),(16,3),(16,6)]},
 '8': {'color':8, 'dr':6,'dc':-4, 'markers':[(1,20),(1,23),(4,19),(5,21)]},
 '4': {'color':4, 'dr':0,'dc':0, 'markers':[(10,15),(11,17),(14,11),(15,16)]},
 '5': {'color':5, 'dr':1,'dc':-12, 'markers':[(15,18),(15,20),(16,21),(17,22)]},
 '9a': {'color':9,'dr':-7,'dc':7, 'markers':[(21,4),(22,9),(24,2),(25,3)]},
 '9b': {'color':9,'dr':-8,'dc':-7,'markers':[(24,13),(24,15)]},
}
# assign actual shape cells to parts by their bounding boxes / components in comp list
comp_by_key={}
for key,p in parts.items():
    col=p['color']
    matches=[cs for v,r0,r1,c0,c1,cs in comps if v==col and ((key=='9a' and (r0,c0)==(21,3)) or (key=='9b' and (r0,c0)==(22,13)) or (key not in ('9a','9b')))]
    if key=='9a': shape=matches[0]
    elif key=='9b': shape=matches[0]
    else:
        # test already one comp per color other than 9
        shape=matches[0]
    comp_by_key[key]=shape
out=[[0]*26 for _ in range(26)]
placements=[]
for key,p in parts.items():
    dr,dc=p['dr'],p['dc']
    for r,c in comp_by_key[key]:
        rr,cc=r+dr,c+dc
        placements.append((rr,cc,p['color'],key,'color'))
        if not (0<=rr<26 and 0<=cc<26): print('out of bounds',key,rr,cc)
        if out[rr][cc] not in (0,p['color']): print('collision shape',key,rr,cc,out[rr][cc],p['color'])
        out[rr][cc]=p['color']
    for r,c in p['markers']:
        rr,cc=r+dr,c+dc
        placements.append((rr,cc,2,key,'marker'))
        if not (0<=rr<26 and 0<=cc<26): print('marker out of bounds',key,rr,cc)
        if out[rr][cc] not in (0,2): print('marker collision',key,rr,cc,out[rr][cc])
        out[rr][cc]=2
[(i, ' '.join(map(str,row))) for i,row in enumerate(out) if any(row)], sum(v!=0 for row in out for v in row), sorted(set((r,c) for r,c,v,k,t in placements if out[r][c]!=v))
